def get_power(x):
    steps = 0
    while x != 1:
        x = x // 2 if x % 2 == 0 else 3 * x + 1
        steps += 1
    return steps


def get_kth(lo, hi, k):
    powers = []
    for x in range(lo, hi + 1):
        powers.append((x, get_power(x)))

    for i in range(len(powers)):
        for j in range(len(powers) - 1 - i):
            a, b = powers[j], powers[j + 1]
            swap = False
            if a[1] > b[1]:
                swap = True
            elif a[1] == b[1] and a[0] > b[0]:
                swap = True
            if swap:
                powers[j], powers[j + 1] = powers[j + 1], powers[j]

    return powers[k - 1][0]


if __name__ == "__main__":
    print(get_kth(12, 15, 2))
    print(get_kth(7, 11, 4))

