import java.util.*;

public class Main {
    static int getPower(int x) {
        long v = x;
        int steps = 0;
        while (v != 1) {
            v = v % 2 == 0 ? v / 2 : 3 * v + 1;
            steps++;
        }
        return steps;
    }

    static int getKth(int lo, int hi, int k) {
        int n = hi - lo + 1;
        int[][] powers = new int[n][2];
        for (int i = 0; i < n; i++) {
            powers[i][0] = lo + i;
            powers[i][1] = getPower(lo + i);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                boolean swap = powers[j][1] > powers[j + 1][1]
                    || (powers[j][1] == powers[j + 1][1] && powers[j][0] > powers[j + 1][0]);
                if (swap) {
                    int[] tmp = powers[j];
                    powers[j] = powers[j + 1];
                    powers[j + 1] = tmp;
                }
            }
        }
        return powers[k - 1][0];
    }

    public static void main(String[] args) {
        System.out.println(getKth(12, 15, 2));
        System.out.println(getKth(7, 11, 4));
    }
}

