        v = v % 2 == 0 ? v / 2 : 3 * v + 1;
        steps++;
    }
    return steps;
}

int getKth(int lo, int hi, int k) {
    vector<pair<int,int>> powers;
    for (int x = lo; x <= hi; x++) powers.push_back({x, getPower(x)});

    int n = powers.size();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            bool swap_needed = powers[j].second > powers[j + 1].second
                || (powers[j].second == powers[j + 1].second && powers[j].first > powers[j + 1].first);
            if (swap_needed) swap(powers[j], powers[j + 1]);
        }
    }
    return powers[k - 1].first;
}

