import java.util.*;

public class Main {
    static Map<Long, Integer> memo = new HashMap<>();

    static int getPower(long x) {
        if (x == 1) return 0;
        if (memo.containsKey(x)) return memo.get(x);
        int result = 1 + getPower(x % 2 == 0 ? x / 2 : 3 * x + 1);
        memo.put(x, result);
        return result;
    }

    static int getKth(int lo, int hi, int k) {
        Integer[] nums = new Integer[hi - lo + 1];
        for (int i = 0; i < nums.length; i++) nums[i] = lo + i;

        Arrays.sort(nums, (a, b) -> {
            int pa = getPower(a), pb = getPower(b);
            if (pa != pb) return pa - pb;
            return a - b;
        });
        return nums[k - 1];
    }

    public static void main(String[] args) {
        System.out.println(getKth(12, 15, 2));
        System.out.println(getKth(7, 11, 4));
    }
}

